{"source":"import json
import sys
from datetime import datetime, timezone


def parse_instant(s):
    """Parse an offset-aware ISO8601 string into a UTC-normalized aware datetime.

    Returns None for non-strings, empty strings, naive datetimes (no offset),
    or unparseable values. Naive/missing/null due values must be skipped.
    """
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s:
        return None
    try:
        dt = datetime.fromisoformat(s)
    except ValueError:
        return None
    if dt.tzinfo is None:
        return None  # naive ISO8601 -> no explicit offset -> skip
    return dt.astimezone(timezone.utc)


def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of = parse_instant(data.get("as_of"))
    if as_of is None:
        # as_of is required and offset-aware; without it we cannot compare.
        print(json.dumps([], ensure_ascii=False))
        return

    results = []
    for r in data.get("reminders", []):
        if not isinstance(r, dict):
            continue
        # Skip completed reminders.
        if r.get("completed"):
            continue
        # Skip missing due key.
        if "due" not in r:
            continue
        due = r.get("due")
        # Skip null.
        if due is None:
            continue
        # Skip naive / unparseable due values.
        due_utc = parse_instant(due)
        if due_utc is None:
            continue
        # Include due AT OR BEFORE as_of, comparing actual instants.
        if due_utc <= as_of:
            results.append((
                due_utc,
                str(r.get("id")),
                r.get("id"),
                r.get("title"),
                due_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
            ))

    # Sort by actual due instant, then by id.
    results.sort(key=lambda x: (x[0], x[1]))

    out = [
        {"id": r[2], "title": r[3], "due_utc": r[4]}
        for r in results
    ]
    # ensure_ascii=False preserves title bytes exactly as UTF-8 (matches input bytes).
    print(json.dumps(out, ensure_ascii=False))


if __name__ == "__main__":
    main()"}

